async function makeSession(u,env){const p=b64(new TextEncoder().encode(JSON.stringify({...u,exp:Math.floor(Date.now()/1000)+1209600})));const s=await crypto.subtle.sign('HMAC',await cryptoKey(env),new TextEncoder().encode(p));return p+'.'+b64(new Uint8Array(s))}
const isAdmin=u=>Boolean(u?.isAdmin&&u.provider==='google'&&ADMIN_EMAILS.has(u.email.toLowerCase()));
const emailEscape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const emailFrame=(title,content,actionUrl='',actionLabel='Abrir mi perfil')=>`<!doctype html><html lang="es"><body style="margin:0;background:#090718;color:#f5f1ff;font-family:Arial,sans-serif"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#090718;padding:28px 12px"><tr><td align="center"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:620px;border:1px solid #66528f;background:#121025"><tr><td style="padding:18px 28px;border-bottom:1px solid #493b6d;color:#b9a3ff;font-size:12px;font-weight:bold;letter-spacing:3px"><table role="presentation" cellspacing="0" cellpadding="0"><tr><td style="vertical-align:middle;padding-right:12px"><img src="https://nnytro.online/assets/nutria-logo.png" width="42" height="42" alt="Nutria de NNytro" style="display:block;width:42px;height:42px;object-fit:contain"></td><td style="vertical-align:middle">SOPORTE NNYTRO<br><span style="color:#b6f3ff;font-size:10px;letter-spacing:2px">COMISIONES</span></td></tr></table></td></tr><tr><td style="padding:28px"><h1 style="margin:0 0 16px;color:#fff;font-size:25px;line-height:1.2">${emailEscape(title)}</h1>${content}${actionUrl?`<p style="margin:26px 0 8px"><a href="${emailEscape(actionUrl)}" style="display:inline-block;padding:13px 18px;background:#a786fa;color:#100b24;text-decoration:none;font-weight:bold">${emailEscape(actionLabel)} →</a></p>`:''}</td></tr><tr><td style="padding:16px 28px;border-top:1px solid #493b6d;color:#b8b0ca;font-size:12px;line-height:1.5">Este mensaje se refiere a una solicitud de comisión. No compartas datos de pago por correo.</td></tr></table></td></tr></table></body></html>`;
const emailParagraph=value=>`<p style="margin:0 0 16px;color:#d9d3e8;font-size:15px;line-height:1.65">${emailEscape(value).replace(/\n/g,'<br>')}</p>`;
const supportMailFrom=value=>{const raw=String(value||'').trim(),match=raw.match(/<([^<>]+)>/),address=(match?.[1]||raw).trim();return address.includes('@')?`Soporte NNytro <${address}>`:raw};
async function mailTo(env,recipient,subject,content,html=''){if(!env.RESEND_API_KEY||!env.MAIL_FROM||!recipient)return false;const r=await fetch('https://api.resend.com/emails',{method:'POST',headers:{authorization:'Bearer '+env.RESEND_API_KEY,'content-type':'application/json'},body:JSON.stringify({from:supportMailFrom(env.MAIL_FROM),to:[recipient],reply_to:env.MAIL_REPLY_TO||env.ADMIN_EMAIL||ADMIN,subject,text:content,...(html?{html}:{})})}),body=await r.json().catch(()=>({}));if(!r.ok)throw Error(`Resend ${r.status}: ${text(body.message||body.error||body.name,300)||'provider rejected the message'}`);if(!body.id)throw Error('Resend accepted no message ID');return true}
async function tryMail(env,recipient,subject,content,html=''){try{return await mailTo(env,recipient,subject,content,html)?'sent':'not_configured'}catch(e){console.error('Order email delivery failed:',e?.message||'unknown provider error');return 'failed'}}
async function notifyDiscordOrder(env,o,items,estimate){
 if(!env.DISCORD_BOT_TOKEN||!/^\d{15,22}$/.test(String(env.DISCORD_NOTIFY_USER_ID||'')))return 'not_configured';
 try{
  const opened=await fetch('https://discord.com/api/v10/users/@me/channels',{method:'POST',headers:{authorization:'Bot '+env.DISCORD_BOT_TOKEN,'content-type':'application/json'},body:JSON.stringify({recipient_id:String(env.DISCORD_NOTIFY_USER_ID)})});
  if(!opened.ok){console.error('Discord order DM channel failed with HTTP '+opened.status);return 'failed'}
  const channel=await opened.json();if(!channel?.id){console.error('Discord order DM returned no channel ID');return 'failed'}
  const itemLines=items.map(item=>`• ${SERVICE_NAMES[item.id]||item.id} × ${Number(item.quantity)||0} — USD ${((Number(item.catalogUsd)||0)*(Number(item.quantity)||0)).toFixed(2)}`).join('\n')||'Sin opciones';
 const content=`🧾 NUEVO PEDIDO NNytro #${o.id.slice(0,8).toUpperCase()}\nCliente: ${text(o.customer_name,100)}\nCorreo: ${text(o.customer_email,200)}\nContacto: ${text(o.contact,160)}\n\n${itemLines}\nEstimación orientativa: USD ${estimate.toFixed(2)}\n\nDetalles:\n${text(o.details,700)||'(sin detalles adicionales)'}\n\nPedido enviado para revisión. No inició ningún pago.`.slice(0,1900);
  const sent=await fetch(`https://discord.com/api/v10/channels/${encodeURIComponent(channel.id)}/messages`,{method:'POST',headers:{authorization:'Bot '+env.DISCORD_BOT_TOKEN,'content-type':'application/json'},body:JSON.stringify({content,allowed_mentions:{parse:[]}})});
  if(!sent.ok){console.error('Discord order DM send failed with HTTP '+sent.status);return 'failed'}
  return 'sent';
 }catch(error){console.error('Discord order DM failed:',error?.message||'unknown provider error');return 'failed'}
}
const ORDER_STATUS_LABELS={requested:'Recibido · pendiente de revisión',accepted:'Pedido aceptado',rejected:'Pedido rechazado',awaiting_full_payment:'Cotización lista · falta el pago completo',awaiting_advance:'Cotización lista · falta el adelanto',advance_paid:'Adelanto confirmado',paid:'Pago completo confirmado',in_progress:'Trabajo en curso',awaiting_balance:'Trabajo terminado · falta el saldo',completed_paid:'Comisión terminada y pagada',cancelled:'Pedido cancelado'};
