const money=n=>Math.round((Number(n)+Number.EPSILON)*100)/100;
const externalSite=env=>{const raw=String(env.PUBLIC_SITE_URL||'').trim();if(!raw)return null;try{const u=new URL(raw);if(u.protocol!=='https:'||u.username||u.password||u.pathname!=='/'||u.search||u.hash||u.hostname==='localhost'||u.hostname==='127.0.0.1')return null;return u.origin}catch{return null}};
const mailSite=env=>{const live=externalSite(env);if(live)return live;const raw=String(env.LOCAL_SITE_URL||'').trim();if(!raw)return null;try{const u=new URL(raw);if(u.protocol!=='http:'||!['localhost','127.0.0.1'].includes(u.hostname)||u.username||u.password||u.pathname!=='/'||u.search||u.hash)return null;return u.origin}catch{return null}};
const MEDIA_LIMIT=24*1024*1024;
const MEDIA_TYPES={ 'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/gif':'gif','video/mp4':'mp4','video/webm':'webm' };
function mediaMatches(type,b){if(type==='image/jpeg')return b[0]===0xff&&b[1]===0xd8&&b[2]===0xff;if(type==='image/png')return b[0]===0x89&&b[1]===0x50&&b[2]===0x4e&&b[3]===0x47;if(type==='image/gif')return String.fromCharCode(...b.slice(0,3))==='GIF';if(type==='image/webp')return String.fromCharCode(...b.slice(0,4))==='RIFF'&&String.fromCharCode(...b.slice(8,12))==='WEBP';if(type==='video/webm')return b[0]===0x1a&&b[1]===0x45&&b[2]===0xdf&&b[3]===0xa3;if(type==='video/mp4')return String.fromCharCode(...b.slice(4,8))==='ftyp';return false}
async function boundedFormRequest(r,limit){
 if(!r.body)return null;
 const reader=r.body.getReader(),chunks=[];
 let length=0;
 try{for(;;){const {done,value}=await reader.read();if(done)break;length+=value.byteLength;if(length>limit){await reader.cancel();return null}chunks.push(value)}}catch{return null}
 const body=new Uint8Array(length);let offset=0;for(const chunk of chunks){body.set(chunk,offset);offset+=chunk.byteLength}
 const headers=new Headers(r.headers);headers.delete('content-length');
 return new Request(r.url,{method:r.method,headers,body});
}
async function uploadMedia(r,env){const who=await userFrom(r,env);if(!isAdmin(who))return fail('Admin access required.',403);if(!env.MEDIA_BUCKET)return fail('R2 media bucket is not configured.',503);const declared=Number(r.headers.get('content-length')||0);if(declared>MEDIA_LIMIT+64*1024)return fail('Media file exceeds the 24 MiB limit.',413);const bounded=await boundedFormRequest(r,MEDIA_LIMIT+64*1024);if(!bounded)return fail('Media file exceeds the 24 MiB limit.',413);let form,file;try{form=await bounded.formData();file=form.get('file')}catch{return fail('Upload must use multipart form data.')}if(!file||typeof file.arrayBuffer!=='function')return fail('Choose a media file.');if(file.size<1||file.size>MEDIA_LIMIT)return fail('Media file exceeds the 24 MiB limit.',413);const type=String(file.type||'').toLowerCase(),ext=MEDIA_TYPES[type];if(!ext)return fail('Supported formats: JPG, PNG, WEBP, GIF, MP4 and WEBM.');const bytes=new Uint8Array(await file.arrayBuffer());if(bytes.length!==file.size||!mediaMatches(type,bytes))return fail('The file contents do not match a supported image or video format.');const key=`gallery/${crypto.randomUUID()}.${ext}`;await env.MEDIA_BUCKET.put(key,bytes,{customMetadata:{purpose:'commission-gallery',mime:type,uploadedBy:who.email.toLowerCase()}});return json({url:new URL('/api/media/'+key,r.url).href,key,size:bytes.length,type},201)}
async function profileAvatar(r,env,who){
 if(!who)return fail('Sign in is required.',401);
 if(!env.MEDIA_BUCKET||!env.DB)return fail('Profile photo storage is not configured.',503);
 const key=`avatars/${await hmacHex(env.SESSION_SECRET,'profile-avatar:'+who.sub)}`;
 if(r.method==='GET'){
  const profile=await env.DB.prepare('SELECT avatar_url FROM users WHERE google_sub=?').bind(who.sub).first();
  if(profile?.avatar_url!=='/api/profile/avatar')return fail('Profile photo not found.',404);
  const object=await env.MEDIA_BUCKET.get(key);if(!object||object.customMetadata?.purpose!=='profile-avatar'||object.customMetadata?.owner!==await hmacHex(env.SESSION_SECRET,who.sub))return fail('Profile photo not found.',404);
  return new Response(object.body,{headers:{'content-type':object.customMetadata.mime,'content-length':String(object.size),'cache-control':'private, no-store','x-content-type-options':'nosniff','content-security-policy':"default-src 'none'; sandbox",'cross-origin-resource-policy':'same-origin'}})
 }
 if(r.method!=='POST')return fail('Method not allowed.',405);
 if(!env.MEDIA_BUCKET.put)return fail('Profile photo storage is not configured.',503);
 const limit=8*1024*1024,declared=Number(r.headers.get('content-length')||0);if(declared>limit+64*1024)return fail('Profile photo exceeds 8 MiB.',413);
 const bounded=await boundedFormRequest(r,limit+64*1024);if(!bounded)return fail('Profile photo exceeds 8 MiB.',413);
 let file;try{file=(await bounded.formData()).get('file')}catch{return fail('Upload must use multipart form data.')}
 if(!file||typeof file.arrayBuffer!=='function'||file.size<1||file.size>limit)return fail('Choose a PNG, JPG or WebP image up to 8 MiB.');
 const mime=String(file.type||'').toLowerCase();if(!['image/png','image/jpeg','image/webp'].includes(mime))return fail('Choose a PNG, JPG or WebP image.');
 const bytes=new Uint8Array(await file.arrayBuffer());if(bytes.length!==file.size||!mediaMatches(mime,bytes))return fail('The photo contents do not match its image format.');
 await env.MEDIA_BUCKET.put(key,bytes,{httpMetadata:{contentType:mime},customMetadata:{purpose:'profile-avatar',mime,owner:await hmacHex(env.SESSION_SECRET,who.sub)}});
 await env.DB.prepare("UPDATE users SET avatar_url='/api/profile/avatar',updated_at=datetime('now') WHERE google_sub=?").bind(who.sub).run();
 return json({avatarUrl:'/api/profile/avatar?v='+Date.now()})
}
async function readMedia(key,env,r){if(!env.MEDIA_BUCKET||!/^gallery\/[0-9a-f-]{36}\.(jpg|png|webp|gif|mp4|webm)$/.test(key))return fail('Media not found.',404);const obj=await env.MEDIA_BUCKET.get(key);if(!obj||obj.customMetadata?.purpose!=='commission-gallery')return fail('Media not found.',404);const type=MEDIA_TYPES[obj.customMetadata?.mime];if(!type||!key.endsWith('.'+type))return fail('Media not found.',404);const who=await userFrom(r,env);if(!isAdmin(who)){if(!env.DB)return fail('Media not found.',404);const requested=new URL(r.url).href;try{const rows=await env.DB.prepare('SELECT process_video_url,final_images_json,reference_images_json FROM commission_posts WHERE is_published=1 ORDER BY published_at DESC LIMIT 100').all();let referenced=false;for(const row of rows.results||[]){if(row.process_video_url===requested){referenced=true;break}for(const field of [row.final_images_json,row.reference_images_json]){let list=[];try{list=JSON.parse(field||'[]')}catch{}if(Array.isArray(list)&&list.some(url=>url===requested)){referenced=true;break}}if(referenced)break}if(!referenced)return fail('Media not found.',404)}catch{return fail('Media not found.',404)}}return new Response(obj.body,{headers:{'content-type':obj.customMetadata.mime,'content-length':String(obj.size),'cache-control':'private, no-store','x-content-type-options':'nosniff','content-security-policy':"default-src 'none'; sandbox",'cross-origin-resource-policy':'same-origin'}})}
async function paypalToken(env){if(!env.PAYPAL_CLIENT_ID||!env.PAYPAL_CLIENT_SECRET||!['sandbox','live'].includes(env.PAYPAL_ENV))throw Error('PayPal is not configured');const root=env.PAYPAL_ENV==='live'?'https://api-m.paypal.com':'https://api-m.sandbox.paypal.com';const r=await fetch(root+'/v1/oauth2/token',{method:'POST',headers:{authorization:'Basic '+btoa(env.PAYPAL_CLIENT_ID+':'+env.PAYPAL_CLIENT_SECRET),'content-type':'application/x-www-form-urlencoded'},body:'grant_type=client_credentials'});if(!r.ok)throw Error('PayPal token request failed '+r.status);const data=await r.json();if(typeof data.access_token!=='string')throw Error('PayPal token missing');return {token:data.access_token,root}}
async function paypalFetch(env,path,token,options={}){const {root}=await Promise.resolve({root:env.PAYPAL_ENV==='live'?'https://api-m.paypal.com':'https://api-m.sandbox.paypal.com'});return fetch(root+path,{...options,headers:{authorization:'Bearer '+token,'content-type':'application/json',...(options.headers||{})}})}
async function hmacHex(secret,message){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret),{name:'HMAC',hash:'SHA-256'},false,['sign']);return [...new Uint8Array(await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(message)))].map(x=>x.toString(16).padStart(2,'0')).join('')}
