 const id=crypto.randomUUID();
 try{await env.DB.prepare("INSERT INTO payments(id,order_id,provider,leg,amount,currency,status,created_at,updated_at) VALUES(?,?,?,?,?,'USD','created',datetime('now'),datetime('now'))").bind(id,o.id,provider,leg,amount).run()}catch{}
