async function reportManualTransfer(env,who,b){if(!who)return fail('Sign in is required.',401);const payment=await env.DB.prepare("SELECT p.*,o.customer_name,o.customer_email FROM payments p JOIN orders o ON o.id=p.order_id WHERE p.id=? AND o.user_sub=? AND p.provider IN ('transfer_usd','transfer_ars')").bind(text(b?.paymentId,80),who.sub).first();if(!payment)return fail('Transfer not found.',404);if(payment.status==='pending')return json({reported:true,alreadyReported:true});if(payment.status!=='created')return fail('This transfer cannot be reported in its current state.',409);let receipt={};try{receipt=JSON.parse(payment.receipt_json||'{}')}catch{}receipt.customerReference=text(b?.reference,120);receipt.reportedAt=new Date().toISOString();const updated=await env.DB.prepare("UPDATE payments SET status='pending',receipt_json=?,updated_at=datetime('now') WHERE id=? AND status='created'").bind(JSON.stringify(receipt),payment.id).run();if(!Number(updated?.meta?.changes))return fail('Transfer state changed. Refresh the order and try again.',409);const t=receipt.transfer||{},moneyLabel=t.currency==='ARS'?`ARS ${Number(t.amountLocal).toFixed(2)} (equivalente USD ${Number(payment.amount).toFixed(2)}, cambio acordado ${Number(t.exchangeRate).toFixed(2)})`:`USD ${Number(payment.amount).toFixed(2)}`,subject=`Transferencia informada · pedido NN-${payment.order_id.slice(0,8)}`,content=`${payment.customer_name} informó una transferencia de ${moneyLabel}. Revisá el movimiento en tu cuenta y confirmalo desde el panel solo si ingresó correctamente.`;try{await mailTo(env,env.ADMIN_EMAIL||ADMIN,subject,content,emailFrame('Transferencia informada',`${emailParagraph(`${payment.customer_name} informó una transferencia para el pedido NN-${payment.order_id.slice(0,8).toUpperCase()}.`)}${emailParagraph(moneyLabel)}${t.alias?emailParagraph(`Alias de destino: ${t.alias}`):''}${receipt.customerReference?emailParagraph(`Referencia informada: ${receipt.customerReference}`):''}${emailParagraph('Revisá el ingreso en tu cuenta antes de confirmar el pago desde el panel.')}`,mailSite(env)?`${mailSite(env)}/perfil-comisiones.html`:''))}catch(e){console.error('Transfer report email failed',e)}return json({reported:true,status:'pending'},201)}
async function verifyManualTransfer(env,who,o,paymentId,accept=true,reason=''){const payment=await env.DB.prepare("SELECT * FROM payments WHERE id=? AND order_id=? AND provider IN ('transfer_usd','transfer_ars') AND status='pending'").bind(text(paymentId,80),o.id).first();if(!payment)return fail('No hay una transferencia pendiente para confirmar.',404);if(!accept){const result=await env.DB.prepare("UPDATE payments SET status='failed',receipt_json=?,updated_at=datetime('now') WHERE id=? AND status='pending'").bind(JSON.stringify({rejectedAt:new Date().toISOString(),reason:text(reason,300)}),payment.id).run();if(!Number(result?.meta?.changes))return fail('La transferencia cambió mientras la revisabas.',409);await event(env,o.id,who.sub,'manual_transfer_rejected',{paymentId:payment.id,reason:text(reason,300)});await notifyOrder(env,o,'payment_reversed',`No se pudo confirmar la transferencia informada. ${text(reason,300)}`);return json({verified:false,rejected:true})}const expected=payment.leg==='full'?'awaiting_full_payment':payment.leg==='advance'?'awaiting_advance':'awaiting_balance',target=payment.leg==='full'?'paid':payment.leg==='advance'?'advance_paid':'completed_paid';if(o.status!==expected)return fail('El pedido ya no está esperando esta etapa de pago.',409);const exactAmount=await paymentAmount(env,o,payment.leg);if(money(exactAmount)!==money(payment.amount))return fail('El importe del pedido cambió. Revisá la cotización y la transferencia antes de confirmar.',409);let receipt={};try{receipt=JSON.parse(payment.receipt_json||'{}')}catch{}receipt.verifiedAt=new Date().toISOString();receipt.verifiedBy=who.email;receipt.adminConfirmed=true;const result=await env.DB.batch([env.DB.prepare("UPDATE orders SET status=?,updated_at=datetime('now') WHERE id=? AND status=? AND EXISTS (SELECT 1 FROM payments p WHERE p.id=? AND p.status='pending' AND p.provider IN ('transfer_usd','transfer_ars') AND p.currency='USD' AND p.amount<=orders.total_usd-COALESCE((SELECT SUM(p2.amount) FROM payments p2 WHERE p2.order_id=orders.id AND p2.currency='USD' AND p2.status='paid' AND p2.verified_at IS NOT NULL),0)+0.005)").bind(target,o.id,expected,payment.id),env.DB.prepare("UPDATE payments SET status='paid',verified_at=datetime('now'),receipt_json=?,updated_at=datetime('now') WHERE id=? AND status='pending' AND EXISTS(SELECT 1 FROM orders WHERE id=payments.order_id AND status=?)").bind(JSON.stringify(receipt),payment.id,target)]);if(!Number(result?.[0]?.meta?.changes)||!Number(result?.[1]?.meta?.changes))return fail('No se pudo confirmar el pago. Actualizá el pedido y verificá que la transferencia siga pendiente.',409);await event(env,o.id,who.sub,'manual_transfer_verified',{paymentId:payment.id,provider:payment.provider,leg:payment.leg,amountUsd:payment.amount,currency:receipt.transfer?.currency||'USD',amountLocal:receipt.transfer?.amountLocal||payment.amount});const order=await env.DB.prepare('SELECT * FROM orders WHERE id=?').bind(o.id).first(),label=receipt.transfer?.currency||'USD',paidAmount=receipt.transfer?.amountLocal||payment.amount;await notifyOrder(env,order,target,`Transferencia revisada y confirmada por NNytro: ${label} ${Number(paidAmount).toFixed(2)} · equivalente a USD ${Number(payment.amount).toFixed(2)}.`);return json({verified:true,order:{id:o.id,status:target}})}
async function setVerifiedPayment(env,payment,canonical,provider){if(!payment||!canonical)return false;let status='pending',canonicalId='',currency='',amount=NaN,external='';
 if(provider==='mercadopago'){status=canonical.status==='approved'?'paid':['rejected','cancelled','refunded','charged_back'].includes(canonical.status)?(canonical.status==='refunded'||canonical.status==='charged_back'?'refunded':'failed'):'pending';canonicalId=String(canonical.id||'');currency=canonical.currency_id;amount=Number(canonical.transaction_amount);external=String(canonical.external_reference||'')}
 else{const cap=canonical;status=cap.status==='COMPLETED'?'paid':['REFUNDED','PARTIALLY_REFUNDED'] .includes(cap.status)?'refunded':['DECLINED','FAILED','VOIDED'] .includes(cap.status)?'failed':'pending';canonicalId=String(cap.id||'');currency=cap.amount?.currency_code;amount=Number(cap.amount?.value);external=String(cap.custom_id||'')}
 if(!canonicalId||external!==payment.id||currency!=='USD'||payment.currency!=='USD'||!Number.isFinite(amount)||money(amount)!==money(payment.amount))return false;
 if(payment.status==='paid'&&status==='paid'&&String(payment.provider_payment_id||'')===canonicalId)return true;
 const receipt=JSON.stringify({provider,id:canonicalId,status:canonical.status,currency,amount,verifiedAt:status==='paid'?new Date().toISOString():null,providerReference:canonical.status_detail||canonical.status});
 if(status==='paid'){
  const expected=payment.leg==='full'?'awaiting_full_payment':payment.leg==='advance'?'awaiting_advance':'awaiting_balance';
  const target=payment.leg==='full'?'paid':payment.leg==='advance'?'advance_paid':'completed_paid';
  // A D1 batch is one transaction. Transition the order first, but only while this
  // exact attempt is pending, the order is at the matching step, and the ledger
  // total including this capture cannot exceed the accepted quote. Then record it.
  const transition=await env.DB.batch([
   env.DB.prepare("UPDATE orders SET status=?,updated_at=datetime('now') WHERE id=? AND status=? AND EXISTS (SELECT 1 FROM payments p WHERE p.id=? AND p.currency='USD' AND p.status IN ('created','pending') AND p.amount<=orders.total_usd-COALESCE((SELECT SUM(p2.amount) FROM payments p2 WHERE p2.order_id=orders.id AND p2.currency='USD' AND p2.status='paid' AND p2.verified_at IS NOT NULL),0)+0.005)").bind(target,payment.order_id,expected,payment.id),
   env.DB.prepare("UPDATE payments SET provider_payment_id=COALESCE(?,provider_payment_id),status='paid',verified_at=COALESCE(verified_at,datetime('now')),receipt_json=?,updated_at=datetime('now') WHERE id=? AND status IN ('created','pending') AND EXISTS (SELECT 1 FROM orders o WHERE o.id=payments.order_id AND o.status=?)").bind(canonicalId,receipt,payment.id,target)
  ]);
  if(!Number(transition?.[0]?.meta?.changes))return false;
  try{const order=await env.DB.prepare('SELECT * FROM orders WHERE id=?').bind(payment.order_id).first();await event(env,order.id,'payment-system','payment_verified',{paymentId:payment.id,provider,leg:payment.leg,amountUsd:payment.amount});await notifyOrder(env,order,target,`Pago confirmado por ${provider}: USD ${Number(payment.amount).toFixed(2)} (${payment.leg}).`)}catch(e){console.error('Payment notification error',e)}return true
 }
 if(status==='refunded'){
  const result=await env.DB.prepare("UPDATE payments SET status='refunded',provider_payment_id=COALESCE(?,provider_payment_id),receipt_json=?,updated_at=datetime('now') WHERE id=? AND status IN ('paid','created','pending')").bind(canonicalId,receipt,payment.id).run();
  if(Number(result?.meta?.changes)){const reason=`Reembolso o contracargo confirmado por ${provider}; el pedido quedó pausado para revisión del pago.`;await env.DB.prepare("UPDATE orders SET status='cancelled',rejection_reason=?,public_consent=0,public_chosen_name=NULL,public_consent_at=NULL,updated_at=datetime('now') WHERE id=? AND status!='cancelled'").bind(reason,payment.order_id).run();await env.DB.prepare("UPDATE commission_posts SET is_published=0,published_at=NULL WHERE order_id=?").bind(payment.order_id).run();try{const order=await env.DB.prepare('SELECT * FROM orders WHERE id=?').bind(payment.order_id).first();await event(env,payment.order_id,'payment-system','payment_refunded',{paymentId:payment.id,provider,amountUsd:payment.amount});await notifyOrder(env,order,'payment_reversed',reason)}catch(e){console.error('Refund notification error',e)}}return true
 }
 // Preserve terminal paid/refunded states against out-of-order provider events.
 await env.DB.prepare("UPDATE payments SET provider_payment_id=COALESCE(?,provider_payment_id),status=?,receipt_json=?,updated_at=datetime('now') WHERE id=? AND status IN ('created','pending')").bind(canonicalId,status,receipt,payment.id).run();return true}
async function verifyMercadoSignature(r,u,env,id){const header=r.headers.get('x-signature')||'',reqid=r.headers.get('x-request-id')||'';if(!env.MERCADOPAGO_WEBHOOK_SECRET||!id||!reqid)return false;const fields=Object.fromEntries(header.split(',').map(x=>x.trim().split('=').map(y=>y.trim())).filter(x=>x.length===2));if(!fields.ts||!fields.v1||!/^\d+$/.test(fields.ts))return false;const timestamp=Number(fields.ts);if(!Number.isFinite(timestamp)||Math.abs(Date.now()-timestamp)>10*60*1000)return false;const expected=await hmacHex(env.MERCADOPAGO_WEBHOOK_SECRET,`id:${String(id).toLowerCase()};request-id:${reqid};ts:${fields.ts};`);return safeEqualHex(expected,fields.v1.toLowerCase())}
async function handlePaymentWebhook(r,env,u){const b=await parse(r)||{},provider=u.searchParams.get('provider');if(provider==='mercadopago'){const id=u.searchParams.get('data.id')||b.data?.id||'';if((b.type&&b.type!=='payment')||(u.searchParams.get('type')&&u.searchParams.get('type')!=='payment'))return json({received:true});if(!await verifyMercadoSignature(r,u,env,id))return fail('Invalid Mercado Pago signature.',401);if(!env.MERCADOPAGO_ACCESS_TOKEN)return fail('Mercado Pago API is not configured.',503);const response=await fetch('https://api.mercadopago.com/v1/payments/'+encodeURIComponent(id),{headers:{authorization:'Bearer '+env.MERCADOPAGO_ACCESS_TOKEN}});if(!response.ok)return fail('Could not verify the Mercado Pago payment.',502);const canonical=await response.json();const payment=await env.DB.prepare("SELECT * FROM payments WHERE (provider='pix' AND provider_payment_id=?) OR (provider='mercadopago' AND id=?) OR (provider='pix' AND id=?)").bind(String(canonical.id),String(canonical.external_reference||''),String(canonical.external_reference||'')).first();if(payment&&!await setVerifiedPayment(env,payment,canonical,'mercadopago'))return fail('Mercado Pago payment did not match the stored quote.',409);return json({received:true,processed:Boolean(payment)})}
 if(provider==='paypal'){if(!env.PAYPAL_WEBHOOK_ID||!env.PAYPAL_CLIENT_ID||!env.PAYPAL_CLIENT_SECRET)return fail('PayPal webhook is not configured.',503);const {token}=await paypalToken(env);const verifyBody={auth_algo:r.headers.get('paypal-auth-algo'),cert_url:r.headers.get('paypal-cert-url'),transmission_id:r.headers.get('paypal-transmission-id'),transmission_sig:r.headers.get('paypal-transmission-sig'),transmission_time:r.headers.get('paypal-transmission-time'),webhook_id:env.PAYPAL_WEBHOOK_ID,webhook_event:b};if(Object.values(verifyBody).some(x=>!x))return fail('PayPal signature headers are incomplete.',401);const vr=await paypalFetch(env,'/v1/notifications/verify-webhook-signature',token,{method:'POST',body:JSON.stringify(verifyBody)});const vd=await parse(vr);if(!vr.ok||vd?.verification_status!=='SUCCESS')return fail('Invalid PayPal webhook signature.',401);if(b.event_type!=='PAYMENT.CAPTURE.COMPLETED'&&b.event_type!=='PAYMENT.CAPTURE.REFUNDED')return json({received:true});const capId=b.resource?.id;if(!capId)return fail('PayPal capture identifier is missing.');const pr=await paypalFetch(env,'/v2/payments/captures/'+encodeURIComponent(capId),token);const canonical=await parse(pr);if(!pr.ok||!canonical)return fail('Could not verify the PayPal capture.',502);const orderId=canonical.supplementary_data?.related_ids?.order_id;const payment=await env.DB.prepare("SELECT * FROM payments WHERE provider='paypal' AND provider_payment_id=? OR provider='paypal' AND provider_order_id=?").bind(String(canonical.id),String(orderId||'')).first();if(payment){if(String(payment.provider_order_id)!==String(orderId||''))return fail('PayPal capture is not linked to the stored order.',409);const or=await paypalFetch(env,'/v2/checkout/orders/'+encodeURIComponent(orderId),token);const order=await parse(or);if(!or.ok||!order)return fail('Could not verify the PayPal order reference.',502);const unit=order.purchase_units?.find(x=>x.reference_id===payment.id&&x.custom_id===payment.id);if(!unit)return fail('PayPal order does not match the stored payment attempt.',409);const captures=unit.payments?.captures||[];if(!captures.some(x=>String(x.id)===String(canonical.id)))return fail('PayPal capture is not part of the stored order.',409);canonical.custom_id=unit.custom_id;canonical.amount=canonical.amount||captures.find(x=>String(x.id)===String(canonical.id))?.amount;if(!await setVerifiedPayment(env,payment,canonical,'paypal'))return fail('PayPal capture did not match the stored quote.',409)}return json({received:true,processed:Boolean(payment)})}
 return fail('Unknown payment provider.',400)}
async function capturePaypal(r,env,who,b){if(!who)return fail('Sign in is required.',401);const payment=await env.DB.prepare("SELECT p.*,o.user_sub,o.status AS order_status FROM payments p JOIN orders o ON o.id=p.order_id WHERE p.id=? AND p.provider='paypal'").bind(text(b?.paymentId,80)).first();if(!payment||payment.user_sub!==who.sub)return fail('Payment not found.',404);if(payment.status==='paid')return json({paid:true,receipt:payment.receipt_json?JSON.parse(payment.receipt_json):null});if(!payment.provider_order_id)return fail('PayPal approval is not complete.',409);if(b?.providerOrderId&&String(b.providerOrderId)!==String(payment.provider_order_id))return fail('PayPal return does not match the stored approval.',409);try{const {token}=await paypalToken(env);let response=await paypalFetch(env,'/v2/checkout/orders/'+encodeURIComponent(payment.provider_order_id)+'/capture',token,{method:'POST',headers:{'paypal-request-id':'capture-'+payment.id},body:'{}'});let data=await parse(response);if(!response.ok&&response.status!==422)throw Error('PayPal capture failed '+response.status);if(!response.ok){response=await paypalFetch(env,'/v2/checkout/orders/'+encodeURIComponent(payment.provider_order_id),token);data=await parse(response);if(!response.ok)throw Error('PayPal order lookup failed '+response.status)}const unit=data.purchase_units?.find(x=>x.reference_id===payment.id||x.custom_id===payment.id);const cap=unit?.payments?.captures?.find(x=>x.status==='COMPLETED')||unit?.payments?.captures?.[0];if(!cap)return json({paid:false,status:data.status||'PENDING',message:'Payment confirmation is still pending.'});cap.custom_id=unit.custom_id||unit.reference_id;cap.supplementary_data={related_ids:{order_id:data.id}};if(!await setVerifiedPayment(env,payment,cap,'paypal'))return fail('PayPal capture does not match the approved quote.',409);return json({paid:cap.status==='COMPLETED',status:cap.status})}catch(e){console.error('PayPal capture failed',e);return fail('PayPal could not confirm this payment.',502)}}
async function updateProfile(env,who,b){const display=text(b?.displayName,80);const avatar=text(b?.avatarUrl,500);if(!display)return fail('Display name is required.');if(avatar&&(avatar!=='/api/profile/avatar'&&!avatar.startsWith('/api/profile/avatar?')&&(!avatar.startsWith('https://')||avatar.length>500)))return fail('Avatar must be a verified HTTPS image or the saved profile photo.');await env.DB.prepare("UPDATE users SET display_name=?,avatar_url=?,updated_at=datetime('now') WHERE google_sub=?").bind(display,avatar,who.sub).run();return json({profile:{name:display,picture:avatar,email:who.email,isAdmin:who.isAdmin}})}
async function event(env,id,actor,type,meta={}){await env.DB.prepare("INSERT INTO order_events(id,order_id,actor_sub,event_type,metadata_json,created_at) VALUES(?,?,?,?,?,datetime('now'))").bind(crypto.randomUUID(),id,actor,type,JSON.stringify(meta)).run()}
async function rateLimit(r,env,path){
 if((r.method!=='POST'&&!(['/api/auth/discord/start','/api/auth/discord/callback','/api/auth/x/start','/api/auth/x/callback'].includes(path)&&r.method==='GET'))||path==='/api/payments/webhook')return null;
 let group='api-write',max=60;
 if(path.startsWith('/api/auth/')){group='login';max=10}
 else if(path==='/api/media/upload'){group='upload';max=8}
 else if(path==='/api/payments/checkout'){group='checkout';max=8}
 if(!env.DB||!env.SESSION_SECRET||env.SESSION_SECRET.length<32)return fail('Request protection is not configured.',503);
 const ip=r.headers.get('cf-connecting-ip')||'local';
 const bucket=await hmacHex(env.SESSION_SECRET,ip+'|'+group);
 const now=Date.now(),minute=Math.floor(now/60000);
 await env.DB.prepare('INSERT INTO api_rate_limits(bucket,minute_bucket,hits,updated_at) VALUES(?,?,1,?) ON CONFLICT(bucket) DO UPDATE SET hits=CASE WHEN api_rate_limits.minute_bucket=excluded.minute_bucket THEN api_rate_limits.hits+1 ELSE 1 END,minute_bucket=excluded.minute_bucket,updated_at=excluded.updated_at').bind(bucket,minute,now).run();
 const row=await env.DB.prepare('SELECT hits FROM api_rate_limits WHERE bucket=?').bind(bucket).first();
 if(Math.random()<0.01)await env.DB.prepare('DELETE FROM api_rate_limits WHERE updated_at<?').bind(now-3600000).run();
 if(Number(row?.hits)>max)return json({error:'Too many requests. Please wait and try again.'},429,{'retry-after':'60'});
 return null;
}
